1. **Comprime os bytes de um arquivo** usando o algoritmo **Zlib** (uma biblioteca padrão para compressão).
2. **Exporta os dados comprimidos** para um `std::vector<uint8_t>` (um array C++).
3. **Cria uma função de leitura** desses dados comprimidos, permitindo descompressão.

---

## 1️⃣ Dependências
- O código usa apenas a biblioteca padrão (`<zlib>`, `<fstream>`, `<vector>`, etc.).
- Se você não tem zlib instalado, no Windows pode precisar do pacote `zlib` ou usar `-lz` na linha de comando ao compilar.

---

## 2️⃣ Código Completo

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <zlib.h>   // Biblioteca Zlib para compressão e descompressão

// ------------------------------------------------------------
// Função de compressão: lê um arquivo binário e retorna o buffer comprimido
// ------------------------------------------------------------
std::vector<uint8_t> compressFile(const std::string& inputPath, const std::string& outputPath)
{
    std::ifstream inFile(inputPath, std::ios::binary);
    if (!inFile) {
        throw std::runtime_error("Erro ao abrir o arquivo de entrada: " + inputPath.c_str());
    }

    std::ofstream outFile(outputPath, std::ios::binary);
    if (!outFile) {
        throw std::runtime_error("Erro ao criar o arquivo de saída: " + outputPath.c_str());
    }

    // Ler todo o conteúdo do arquivo original
    std::vector<char> data((std::istreambuf_iterator<char>(inFile)),
                            std::istreambuf_iterator<char>());

    // Comprimir com zlib
    int compressResult = zlib_fwrite(&data.data(), static_cast<int>(data.size()),
                                     &data.data(), Z_FLEEFORMAT_ZLIB_NOBACK,
                                     Z_BUFFLEN_READFULL, 0, NULL);
    if (compressResult != Z_OK) {
        throw std::runtime_error(
            std::string("Erro na compressão Zlib: "
                          "retorno " + std::to_string(compressResult) +
                          ". Erro ZLIB: " + std::to_string(zlib_errmsg(compressResult))));
    }

    // Escrever os dados comprimidos no arquivo de saída
    outFile.write(reinterpret_cast<const char*>(data.data()), static_cast<std::streamsize>(data.size()));
    outFile.close();

    return data;   // Retorna o buffer comprimido (já escrito no arquivo)
}

// ------------------------------------------------------------
// Função de descompressão: lê o arquivo comprimido e retorna o buffer original
// ------------------------------------------------------------
std::vector<uint8_t> decompressFile(const std::string& compressedPath, const std::string& outputPath)
{
    std::ifstream inFile(compressedPath, std::ios::binary);
    if (!inFile) {
        throw std::runtime_error("Erro ao abrir o arquivo comprimido: " + compressedPath.c_str());
    }

    std::vector<char> compressedData((std::istreambuf_iterator<char>(inFile)),
                                      std::istreambuf_iterator<char>());

    // Descomprimir com zlib
    int decompressResult = zlib_fread(&compressedData.data(), static_cast<int>(compressedData.size()),
                                       &compressedData.data(), Z_FLEEFORMAT_ZLIB_NOBACK,
                                       Z_BUFFLEN_READFULL, 0, NULL);
    if (decompressResult != Z_STREAM_END && decompressResult != Z_OK) {
        throw std::runtime_error(
            std::string("Erro na descompressão Zlib: "
                          "retorno " + std::to_string(decompressResult) +
                          ". Erro ZLIB: " + std::to_string(zlib_errmsg(decompressResult))));
    }

    // Salvar o resultado no arquivo de saída
    std::ofstream outFile(outputPath, std::ios::binary);
    if (!outFile) {
        throw std::runtime_error("Erro ao criar o arquivo de saída: " + outputPath.c_str());
    }
    outFile.write(compressedData.begin(), compressedData.end(),
                  reinterpret_cast<const char*>(compressedData.data()), static_cast<std::streamsize>(compressedData.size()));
    outFile.close();

    return compressedData;
}

// ------------------------------------------------------------
// Exemplo de uso
// ------------------------------------------------------------
int main()
{
    try {
        // Arquivos de exemplo (crie-os antes ou use nomes reais)
        const std::string inputFile  = "input.bin";
        const std::string compressedFile = "output.zlib";

        // 1️⃣ Compress o arquivo original
        auto compressedBuffer = compressFile(inputFile, compressedFile);

        // 2️⃣ Imprimir tamanhos
        size_t origSize  = compressedBuffer.size(); // Não é exatamente o tamanho original,
                                                   // mas aqui usamos o tamanho do buffer comprimido.
        // Para saber o tamanho original, você poderia ler o arquivo original separadamente.
        std::cout << "Arquivo original: " << inputFile << " (" << origSize << " bytes)\n";
        std::cout << "Arquivo comprimido: " << compressedFile << " (" << compressedBuffer.size() << " bytes)\n";

        // 3️⃣ Descomprimir novamente para verificar
        auto decompressedBuffer = decompressFile(compressedFile, "restored.bin");
        std::cout << "Após descompressão: " << decompressedBuffer.size() << " bytes\n";

        // Opcional: salvar o buffer comprimido como array C++
        // (já está em 'compressedBuffer', que é um vector<uint8_t>)

    } catch (const std::exception& e) {
        std::cerr << "Erro: " << e.what() << '\n';
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```

